#include <vector>
#include <array>
#include <cstddef>
#include <omp.h>

/*  Vector x contains values between 0 and 100, inclusive.
    Count the number of values in [0,10), [10,20), …, [90,100]
    and store the counts in `bins`.  The implementation is safe for
    any number of OpenMP threads. */
void binsBy10Count(const std::vector<double>& x,
                   std::array<std::size_t, 10>& bins)
{
    // Initialise the output bins.
    for (std::size_t i = 0; i < bins.size(); ++i) bins[i] = 0;

    #pragma omp parallel
    {
        // Private copy for each thread – no race conditions while counting.
        std::array<std::size_t, 10> local{};
        local.fill(0);

        #pragma omp for nowait
        for (std::size_t i = 0; i < x.size(); ++i) {
            double v = x[i];

            // Determine the bin index.
            // Values are in [0,100]; the last bin must also contain 100.
            int idx = (v == 100.0) ? 9 : static_cast<int>(v / 10.0);
            if (idx < 0) idx = 0;
            if (idx > 9) idx = 9;   // safety guard for out‑of‑range data

            ++local[idx];
        }

        // Merge the thread‑local results into the shared `bins`.
        #pragma omp critical
        {
            for (std::size_t j = 0; j < bins.size(); ++j) {
                bins[j] += local[j];
            }
        }
    }
}
